    72	/**
    73	 * gnutls_pkcs12_bag_deinit:
    74	 * @bag: A pointer to the type to be initialized
    75	 *
    76	 * This function will deinitialize a PKCS12 Bag structure.
    77	 **/
    78	void gnutls_pkcs12_bag_deinit(gnutls_pkcs12_bag_t bag)
    79	{
    80	        if (!bag)
    81	                return;
    82	
    83	        _pkcs12_bag_free_data(bag);
    84	
    85	        gnutls_free(bag);
