    88	/**
    89	 * gnutls_pkcs12_bag_get_type:
    90	 * @bag: The bag
    91	 * @indx: The element of the bag to get the type
    92	 *
    93	 * This function will return the bag's type.
    94	 *
    95	 * Returns: On error a negative error value or one of the #gnutls_pkcs12_bag_type_t enumerations.
    96	 **/
    97	int
    98	gnutls_pkcs12_bag_get_type(gnutls_pkcs12_bag_t bag, unsigned indx)
    99	{
   100	        if (bag == NULL) {
   101	                gnutls_assert();
   102	                return GNUTLS_E_INVALID_REQUEST;
   103	        }
   104	
   105	        if (indx >= bag->bag_elements)
   106	                return GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
   107	        return bag->element[indx].type;
   108	}
