   160	#define X509_CERT_OID "1.2.840.113549.1.9.22.1"
   161	#define X509_CRL_OID  "1.2.840.113549.1.9.23.1"
   162	#define RANDOM_NONCE_OID "1.2.840.113549.1.9.25.3"
   163	
   164	int
   165	_pkcs12_decode_crt_bag(gnutls_pkcs12_bag_type_t type,
   166	                       const gnutls_datum_t * in, gnutls_datum_t * out)
   167	{
   168	        int ret;
   169	        ASN1_TYPE c2 = ASN1_TYPE_EMPTY;
   170	
   171	        switch (type) {
   172	        case GNUTLS_BAG_CERTIFICATE:
   173	                if ((ret = asn1_create_element(_gnutls_get_pkix(),
   174	                                               "PKIX1.pkcs-12-CertBag",
   175	                                               &c2)) != ASN1_SUCCESS) {
   176	                        gnutls_assert();
   177	                        ret = _gnutls_asn2err(ret);
   178	                        goto cleanup;
   179	                }
   180	
   181	                ret = asn1_der_decoding(&c2, in->data, in->size, NULL);
   182	                if (ret != ASN1_SUCCESS) {
   183	                        gnutls_assert();
   184	                        ret = _gnutls_asn2err(ret);
   185	                        goto cleanup;
   186	                }
   187	
   188	                ret =
   189	                    _gnutls_x509_read_string(c2, "certValue", out,
   190	                                             ASN1_ETYPE_OCTET_STRING, 1);
   191	                if (ret < 0) {
   192	                        gnutls_assert();
   193	                        goto cleanup;
   194	                }
   195	                break;
   196	
   197	        case GNUTLS_BAG_CRL:
   198	                if ((ret = asn1_create_element(_gnutls_get_pkix(),
   199	                                               "PKIX1.pkcs-12-CRLBag",
   200	                                               &c2)) != ASN1_SUCCESS) {
   201	                        gnutls_assert();
   202	                        ret = _gnutls_asn2err(ret);
   203	                        goto cleanup;
   204	                }
   205	
   206	                ret = asn1_der_decoding(&c2, in->data, in->size, NULL);
   207	                if (ret != ASN1_SUCCESS) {
   208	                        gnutls_assert();
   209	                        ret = _gnutls_asn2err(ret);
   210	                        goto cleanup;
   211	                }
   212	
   213	                ret =
   214	                    _gnutls_x509_read_string(c2, "crlValue", out,
   215	                                             ASN1_ETYPE_OCTET_STRING, 1);
   216	                if (ret < 0) {
   217	                        gnutls_assert();
   218	                        goto cleanup;
   219	                }
   220	                break;
   221	
   222	        case GNUTLS_BAG_SECRET:
   223	                if ((ret = asn1_create_element(_gnutls_get_pkix(),
   224	                                               "PKIX1.pkcs-12-SecretBag",
   225	                                               &c2)) != ASN1_SUCCESS) {
   226	                        gnutls_assert();
   227	                        ret = _gnutls_asn2err(ret);
   228	                        goto cleanup;
   229	                }
   230	
   231	                ret = asn1_der_decoding(&c2, in->data, in->size, NULL);
   232	                if (ret != ASN1_SUCCESS) {
   233	                        gnutls_assert();
   234	                        ret = _gnutls_asn2err(ret);
   235	                        goto cleanup;
   236	                }
   237	
   238	                ret =
   239	                    _gnutls_x509_read_string(c2, "secretValue", out,
   240	                                             ASN1_ETYPE_OCTET_STRING, 1);
   241	                if (ret < 0) {
   242	                        gnutls_assert();
   243	                        goto cleanup;
   244	                }
   245	                break;
   246	
   247	        default:
   248	                gnutls_assert();
   249	                asn1_delete_structure(&c2);
   250	                return GNUTLS_E_UNIMPLEMENTED_FEATURE;
   251	        }
   252	
   253	        asn1_delete_structure(&c2);
   254	
   255	        return 0;
   256	
   257	
   258	      cleanup:
   259	
   260	        asn1_delete_structure(&c2);
   261	        return ret;
   262	}
