   433	/**
   434	 * gnutls_pkcs12_bag_set_crt:
   435	 * @bag: The bag
   436	 * @crt: the certificate to be copied.
   437	 *
   438	 * This function will insert the given certificate into the
   439	 * bag. This is just a wrapper over gnutls_pkcs12_bag_set_data().
   440	 *
   441	 * Returns: the index of the added bag on success, or a negative
   442	 * value on failure.
   443	 **/
   444	int
   445	gnutls_pkcs12_bag_set_crt(gnutls_pkcs12_bag_t bag, gnutls_x509_crt_t crt)
   446	{
   447	        int ret;
   448	        gnutls_datum_t data;
   449	
   450	        if (bag == NULL) {
   451	                gnutls_assert();
   452	                return GNUTLS_E_INVALID_REQUEST;
   453	        }
   454	
   455	        ret = _gnutls_x509_der_encode(crt->cert, "", &data, 0);
   456	        if (ret < 0) {
   457	                gnutls_assert();
