import struct

def encode_length(length):
    """DER length encoding"""
    if length < 0x80:
        return bytes([length])
    elif length < 0x100:
        return bytes([0x81, length])
    elif length < 0x10000:
        return bytes([0x82, (length >> 8) & 0xff, length & 0xff])
    else:
        return bytes([0x83, (length >> 16) & 0xff, (length >> 8) & 0xff, length & 0xff])

def make_sequence(content):
    return b'\x30' + encode_length(len(content)) + content

def make_set(content):
    return b'\x31' + encode_length(len(content)) + content

def make_octet_string(content):
    return b'\x04' + encode_length(len(content)) + content

def make_integer(value):
    """Encode a small non-negative integer"""
    if value == 0:
        return b'\x02\x01\x00'
    bs = []
    v = value
    while v > 0:
        bs.insert(0, v & 0xff)
        v >>= 8
    if bs[0] & 0x80:
        bs.insert(0, 0)
    return b'\x02' + encode_length(len(bs)) + bytes(bs)

def make_oid(oid_str):
    """Encode an OID from dotted string"""
    parts = [int(x) for x in oid_str.split('.')]
    # First two components encoded as 40*first + second
    encoded = [40 * parts[0] + parts[1]]
    for p in parts[2:]:
        if p < 128:
            encoded.append(p)
        else:
            # base-128 encoding
            digits = []
            val = p
            while val > 0:
                digits.insert(0, val & 0x7f)
                val >>= 7
            for i in range(len(digits) - 1):
                digits[i] |= 0x80
            encoded.extend(digits)
    return b'\x06' + encode_length(len(encoded)) + bytes(encoded)

def make_explicit(tag_num, content):
    """Context-specific constructed explicit tag"""
    tag_byte = 0xa0 | tag_num
    return bytes([tag_byte]) + encode_length(len(content)) + content

